import hou
import fxhoudinimcp_server.startup as mcp

if mcp.is_running():
    hou.ui.setStatusMessage(
        f"FXHoudini-MCP already running on port {mcp.get_port()}"
    )
else:
    try:
        mcp.start()
    except Exception as exc:
        hou.ui.displayMessage(
            f"Could not start the FXHoudini-MCP server:\n\n{exc}",
            severity=hou.severityType.Error,
            title="FXHoudini-MCP",
        )
    else:
        hou.ui.setStatusMessage(
            f"FXHoudini-MCP started on port {mcp.get_port()}"
        )
